/*
 * mugen_fields.h -- named offsets of the engine's main structures.
 *
 * The engine reaches structure fields through computed addresses
 * (record + offset). These names replace the numeric offsets; the values
 * are unchanged. Evidence classes: VERIFIED (read or written with a known
 * meaning, or checked at run time), STRONGLY INFERRED (role certain, exact
 * meaning from the triggers/controllers that use the field). Full map and
 * method: engine/struct-map.md. Generated by tools/translate/fields.py.
 *
 * Note: values are word indices for int * bases (PL_, G_) and byte
 * offsets for byte-addressed bases (PLB_, CD_, ARRAY_, ELEM_).
 */
